files.content:
[hidden] { display: none !important; }

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: #e0e0e0;
  padding: 16px;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 12px;
  padding: 24px;
  max-width: 420px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 20px;
  color: #e94560;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.elevator-display {
  background: #0f3460;
  border: 3px solid #e94560;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  position: relative;
  min-height: 100px;
}

.floor-display {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.floor-display .label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #a0a0b0;
}

.floor-display .value {
  font-size: 2.5rem;
  font-weight: bold;
  color: #e94560;
  font-family: 'Courier New', monospace;
  line-height: 1;
}

.direction-display {
  font-size: 2rem;
  color: #e94560;
  font-family: monospace;
}

.doors {
  display: flex;
  gap: 2px;
  height: 60px;
  width: 60px;
  position: relative;
  overflow: hidden;
  border: 2px solid #0f3460;
  border-radius: 4px;
  background: #0a0a1a;
}

.door {
  flex: 1;
  background: #e94560;
  transition: transform 0.3s ease;
}

.door.left {
  transform-origin: left;
}

.door.right {
  transform-origin: right;
}

.doors.open .door.left {
  transform: translateX(-100%);
}

.doors.open .door.right {
  transform: translateX(100%);
}

.panel {
  margin-bottom: 16px;
}

.buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.floor-btn {
  padding: 14px 0;
  font-size: 1.25rem;
  font-weight: bold;
  font-family: 'Courier New', monospace;
  background: #0f3460;
  color: #e0e0e0;
  border: 2px solid #1a1a2e;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  position: relative;
  user-select: none;
}

.floor-btn:hover {
  background: #1a4a7a;
  border-color: #e94560;
}

.floor-btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.floor-btn:active {
  transform: scale(0.95);
  background: #e94560;
  color: #fff;
}

.floor-btn.pending {
  background: #e94560;
  color: #fff;
  border-color: #ff6b81;
  box-shadow: 0 0 8px rgba(233, 69, 96, 0.6);
}

.floor-btn.pending::after {
  content: '';
  position: absolute;
  top: 4px;
  right: 4px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #fff;
  animation: blink 1s infinite;
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

.hint {
  text-align: center;
  font-size: 0.85rem;
  color: #a0a0b0;
  line-height: 1.4;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.2rem;
  }
  .floor-display .value {
    font-size: 2rem;
  }
  .floor-btn {
    padding: 12px 0;
    font-size: 1.1rem;
  }
  .elevator-display {
    min-height: 80px;
    padding: 12px;
  }
  .doors {
    height: 48px;
    width: 48px;
  }
}

(function () {
  'use strict';

  var currentFloor = 1;
  var direction = 'idle';
  var queue = [];
  var moving = false;
  var doorsOpen = false;
  var doorTimer = null;
  var moveTimer = null;

  var currentFloorEl = document.getElementById('currentFloor');
  var directionEl = document.getElementById('direction');
  var doorsEl = document.querySelector('.doors');
  var buttons = document.querySelectorAll('.floor-btn');

  function updateDisplay() {
    currentFloorEl.textContent = currentFloor;
    var arrow = '●';
    var label = 'idle';
    if (direction === 'up') { arrow = '▲'; label = 'up'; }
    else if (direction === 'down') { arrow = '▼'; label = 'down'; }
    directionEl.textContent = arrow;
    directionEl.setAttribute('aria-label', 'Direction: ' + label);
  }

  function updateButtons() {
    buttons.forEach(function (btn) {
      var floor = parseInt(btn.getAttribute('data-floor'), 10);
      if (queue.indexOf(floor) !== -1) {
        btn.classList.add('pending');
      } else {
        btn.classList.remove('pending');
      }
    });
  }

  function openDoors(callback) {
    doorsOpen = true;
    doorsEl.classList.add('open');
    doorTimer = setTimeout(function () {
      doorsEl.classList.remove('open');
      doorsOpen = false;
      doorTimer = null;
      if (callback) callback();
    }, 800);
  }

  function processQueue() {
    if (queue.length === 0) {
      moving = false;
      direction = 'idle';
      updateDisplay();
      return;
    }

    var target = queue[0];

    if (currentFloor === target) {
      queue.shift();
      updateButtons();
      openDoors(function () {
        processQueue();
      });
      return;
    }

    direction = target > currentFloor ? 'up' : 'down';
    moving = true;
    updateDisplay();

    moveTimer = setTimeout(function () {
      moveTimer = null;
      if (direction === 'up') {
        currentFloor++;
      } else {
        currentFloor--;
      }
      updateDisplay();
      processQueue();
    }, 1000);
  }

  function addToQueue(floor) {
    if (queue.indexOf(floor) !== -1) return;
    if (floor === currentFloor && !moving && !doorsOpen) {
      openDoors();
      return;
    }
    queue.push(floor);
    updateButtons();
    if (!moving && !doorsOpen) {
      processQueue();
    }
  }

  buttons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var floor = parseInt(btn.getAttribute('data-floor'), 10);
      addToQueue(floor);
    });
  });

  updateDisplay();
  updateButtons();
})();
